before:
import { test, expect } from "@playwright/test";

test.describe('Filtrage des événements par salle et date sur la page de catégorie', () => {
  test('User clicks Voir Plus to load more events', async ({ page }) => {
    await page.goto('https://teskerti.tn/category/spectacle');

    // TODO: select a room and a date and click "Recherche"

    // And: the results list displays events
    await page.locator('#dynamic_data .tour_container').first().scrollIntoViewIfNeeded();
    await expect(page.locator('#dynamic_data .tour_container').first()).toBeVisible();

    // When: the user clicks the "Voir Plus" button
    const loadMoreBtn = page.locator('#load_more');
    await expect(loadMoreBtn).toBeVisible();
    await loadMoreBtn.click();

    // Then: additional events are displayed
    await page.locator('#dynamic_data .tour_container').first().scrollIntoViewIfNeeded();
    await expect(page.locator('#dynamic_data .tour_container').first()).toBeVisible();
  });
});

